cat <<EOF > /tmp/repro.py
from rich.text import Text

t = Text()
try:
    t.append_tokens([])
    print("Empty list: OK")
except Exception as e:
    print(f"Empty list: {e}")

try:
    t.append_tokens(iter([]))
    print("Empty iter: OK")
except Exception as e:
    print(f"Empty iter: {e}")

try:
    t.append_tokens([("hello", "red")])
    print("Single token: OK")
except Exception as e:
    print(f"Single token: {e}")

try:
    t.append_tokens([("hello", None)])
    print("Token without style: OK")
except Exception as e:
    print(f"Token without style: {e}")

try:
    t.append_tokens([("", "red")])
    print("Empty content: OK")
except Exception as e:
    print(f"Empty content: {e}")
except Exception as e:
    print(f"Empty content: {e}")

EOF
python3 /tmp/repro.py
